      <Path
        d="M5 7h14M9 7V4.5h6V7M7 7l1 13h8l1-13"
        stroke="#C0392B"
        strokeWidth={K}
        fill="none"
        strokeLinejoin="round"
        strokeLinecap="round"
      />
    </>
  )
}

export const CikisIkonu = () => {
  const renk = useRenk()
  return govde(
    <>
      <Path
        d="M14 4.5H6v15h8"
        stroke={renk.metin}
        strokeWidth={K}
        fill="none"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      <Path
        d="M12.5 12H20m0 0l-3-3m3 3l-3 3"
        stroke={renk.metin}
        strokeWidth={K}
        fill="none"
        strokeLinecap="round"
