    ;(gonderimDurumu as jest.Mock).mockResolvedValue({ kalanSaniye: 0, kalanHak: 3 })
    ;(supabase.auth.signInWithOtp as jest.Mock).mockClear()

    // Sayac 60 sn'den basliyor; "Tekrar gönder" ancak 0'da gorunuyor.
