    // ekrani yeniden aciyoruz.
    ;(gonderimDurumu as jest.Mock).mockResolvedValue({ kalanSaniye: 0, kalanHak: 3 })
    screen.unmount()
    ;(gonderimDurumu as jest.Mock).mockResolvedValueOnce({ kalanSaniye: 0, kalanHak: 3 })
